import numpy as np, pandas as pd
from alphacrafter.sim.utils import get_index_daily_data
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
# Lagged cross-sectional relative-strength signal: asset 20d return minus same-day universe median,
# scaled by its trailing 20d downside volatility. All inputs through t-1.
prices={}
for s in U:
 d=get_index_daily_data(s,days=4000)
 if d is not None and len(d): prices[s]=d.set_index('date')['close'].astype(float)
p=pd.DataFrame(prices).sort_index().ffill()
r=np.log(p).diff()
raw=np.log(p/p.shift(20))
down=r.where(r<0).rolling(20,min_periods=10).std()
f=(raw.sub(raw.median(axis=1),axis=0)/down.replace(0,np.nan)).shift(1)
fwd=np.log(p.shift(-1)/p)
rows=[]; daily=[]
for dt in f.index:
 x=f.loc[dt]; y=fwd.loc[dt]; z=pd.concat([x,y],axis=1).dropna()
 if len(z)>=8 and z.iloc[:,0].nunique()>1 and z.iloc[:,1].nunique()>1:
  ic=z.iloc[:,0].corr(z.iloc[:,1],method='spearman'); daily.append(ic); rows.append((dt,len(z)))
ser=pd.Series(daily)
print('dates',len(ser),'avg_n',np.mean([n for _,n in rows]),'coverage',f.stack().count()/(len(f)*len(U)))
print('daily_ic %.8f icir %.8f hit %.5f turnover %.8f'%(ser.mean(),ser.mean()/ser.std(),(ser>0).mean(),f.rank(axis=1).diff().abs().mean().mean()))
for h in [5,10]:
 yy=np.log(p.shift(-h)/p); vals=[]
 for dt in f.index:
  z=pd.concat([f.loc[dt],yy.loc[dt]],axis=1).dropna()
  if len(z)>=8 and z.iloc[:,0].nunique()>1 and z.iloc[:,1].nunique()>1: vals.append(z.iloc[:,0].corr(z.iloc[:,1],method='spearman'))
 print('%dd_ic %.8f'%(h,np.nanmean(vals)))
for name,mask in [('2020-22',(f.index<'2023-01-01')),('2023-24',(f.index>='2023-01-01')&(f.index<'2025-01-01')),('2025-26',(f.index>='2025-01-01')&(f.index<'2027-01-01')),('2027-28',(f.index>='2027-01-01'))]:
 q=[]
 for dt,(v,n) in zip([x[0] for x in rows],rows):
  if mask.loc[dt] if hasattr(mask,'loc') else False:q.append(v)
 print(name, np.mean(q) if q else np.nan, len(q))

