R=pd.concat(S,axis=1).sort_index(); eq=R[['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX']].mean(axis=1)
rows=[]
for s in U:
 r=R[s]; down=eq<0
