import numpy as np, pandas as pd
from alphacrafter.sim.utils import get_index_daily_data

U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
D={}
for s in U:
    x=get_index_daily_data(s, days=5000)
    if x is not None and len(x):
        x=x.copy(); x['date']=pd.to_datetime(x['date']); D[s]=x.set_index('date')['close'].astype(float)
p=pd.DataFrame(D).sort_index().ffill()
# strictly lagged signal at date t: return through t, normalized by trailing vol
r=p.pct_change()
vol=r.rolling(30,min_periods=15).std()*np.sqrt(252)
sig=(p/p.shift(20)-1)/vol
# modest cross-sectional breadth dampener, based only on current information
breadth=(r.rolling(20).sum()>0).mean(axis=1)
sig=sig.mul((0.5+breadth),axis=0)
rows=[]
for h in [5,10,20]:
    ics=[]; dates=[]; ns=[]; turnovers=[]
    prev=None
    for i in range(len(p)-h):
        d=p.index[i]
        f=sig.iloc[i]; y=p.iloc[i+h]/p.iloc[i]-1
        z=pd.concat([f,y],axis=1).dropna();
        if len(z)>=8:
            ic=z.iloc[:,0].rank().corr(z.iloc[:,1].rank())
            if np.isfinite(ic): ics.append(ic); dates.append(d); ns.append(len(z))
        rr=f.dropna().rank();
        if prev is not None:
            q=pd.concat([rr,prev],axis=1).dropna()
            if len(q): turnovers.append((q.iloc[:,0]!=q.iloc[:,1]).mean())
        prev=rr
    a=np.array(ics); rows.append((h,len(a),np.mean(ns),a.mean(),a.std(ddof=1),a.mean()/a.std(ddof=1)*np.sqrt(252) if a.std(ddof=1)>0 else np.nan,(a>0).mean(),np.mean(turnovers)))
print('dates',p.index.min(),p.index.max(),'assets',len(p.columns),'rows',len(p))
for x in rows: print('H IC n avgN IC ICIR hit turnover',x)
print('regimes')
for yr,g in pd.Series(ics,index=dates).groupby(lambda x:x.year): print(yr, len(g), round(g.mean(),5))
print('coverage',sig.notna().sum(axis=1).mean()/len(U))

