import numpy as np, pandas as pd
from alphacrafter.sim.utils import get_index_daily_data

U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
D={}
for s in U:
    x=get_index_daily_data(s, days=5000)
    if x is not None and len(x):
        x=x.copy(); x['date']=pd.to_datetime(x['date']); D[s]=x.set_index('date')['close'].astype(float)
p=pd.DataFrame(D).sort_index().ffill()
# candidate: acceleration (recent 20d return minus prior 40d return), risk normalized;
# cross-asset breadth conditioning: when breadth is weak, retain only assets with positive recent trend
r20=p.pct_change(20); r40=p.pct_change(40); r60=p.pct_change(60)
vol=p.pct_change().rolling(20).std()*np.sqrt(252)
breadth=(r20>0).mean(axis=1)
# interpretable relative-strength acceleration, with weak-breadth penalty on laggards
f=(r20-r40/2)/(vol+1e-8)
f=f.where(breadth>=0.5, f.clip(lower=0))

def eval(h):
    vals=[]; turnovers=[]; counts=[]
    for i in range(len(p)-h):
        d=p.index[i]; j=i
        a=f.iloc[i].replace([np.inf,-np.inf],np.nan); y=p.iloc[i+h]/p.iloc[i]-1
        z=pd.concat([a,y.rename('y')],axis=1).dropna()
        if len(z)>=8:
            vals.append(z.iloc[:,0].corr(z.y)); counts.append(len(z))
        if i>0:
            q=f.iloc[i].rank(pct=True); q0=f.iloc[i-1].rank(pct=True)
            turnovers.append((q-q0).abs().mean())
    v=np.array(vals); return len(v),np.mean(v),np.mean(v)/(np.std(v,ddof=1)+1e-12),np.mean(counts),np.mean(turnovers)
print('data dates',len(p),'assets',len(p.columns),'range',p.index.min(),p.index.max())
for h in [5,10,20]: print(h,eval(h))
# yearly 10d
h=10
for yr in sorted(set(p.index.year)):
    vals=[]
    for i in range(len(p)-h):
      if p.index[i].year!=yr: continue
      z=pd.concat([f.iloc[i],(p.iloc[i+h]/p.iloc[i]-1).rename('y')],axis=1).dropna()
      if len(z)>=8: vals.append(z.iloc[:,0].corr(z.y))
    if vals: print('year',yr,len(vals),round(float(np.mean(vals)),5))

