R=P.pct_change(); down=R.where(R<0,0).rolling(20,min_periods=15).std();
# directional efficiency: net displacement / total absolute movement, bounded [0,1]
eff=R.rolling(20,min_periods=15).sum().abs()/(R.abs().rolling(20,min_periods=15).sum()+1e-12)
