import pandas as pd, numpy as np, glob
from scipy.stats import spearmanr
assets=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
D={}
for a in assets:
 p='../persistent/index_data/'+a+'.csv'
 try:
  x=pd.read_csv(p,parse_dates=['date']).set_index('date'); D[a]=x
 except: pass
prices=pd.concat({a:D[a]['close'] for a in D},axis=1).sort_index()
r=prices.pct_change()
# Range-efficiency reversal: negative signed return divided by path roughness, then damped by recent range.
# factor = -20d return / (sum abs daily returns over 20d + eps), higher means rebound after inefficient decline.
f=-(prices/prices.shift(20)-1)/(r.abs().rolling(20).sum()+1e-8)
rows=[]
for h in [5,10,20]:
  ics=[]; n=[]; turnovers=[]
  for i in range(20,len(prices)-h):
   z=f.iloc[i]; y=(prices.iloc[i+h]/prices.iloc[i]-1)
   ok=z.notna()&y.notna()
   if ok.sum()>=8:
    ics.append(spearmanr(z[ok],y[ok]).statistic); n.append(ok.sum())
   if i>20:
    old=f.iloc[i-1]; oo=old.notna()&z.notna()
    if oo.sum(): turnovers.append(np.mean((z[oo].rank(pct=True)-old[oo].rank(pct=True)).abs()))
  a=np.array(ics); rows.append((h,len(a),np.mean(n),np.mean(a),np.mean(a)/np.std(a,ddof=1),np.mean(a>0),np.mean(turnovers)))
print('assets',len(D),'dates',len(prices),'cutoff',prices.index.max().date())
for x in rows: print('horizon dates avgN IC ICIR hit turnover',x)
print('coverage',f.notna().mean().mean())

