# short-term reversal amplified when volatility is elevated, smooth bounded weight
fac=-r.rolling(5,min_periods=5).sum()*(shock.clip(0.5,2.5))
fwd=p.shift(-5)/p-1
ics=[]; ns=[]; prev=None; turns=[]
