p=pd.concat(px,axis=1).sort_index().loc[:'2033-01-19']; r=p.pct_change(); mom=p.pct_change(20)
down=r.where(r<0).rolling(30).std(); quality=mom/down.replace(0,np.nan)
b=(mom>0).sum(axis=1)/mom.notna().sum(axis=1)
